import { useEffect, useMemo, useRef, useState } from "react";
import {
  ArrowDownRight, ArrowLeftRight, ArrowUpRight, BarChart3, Bell, Check, ChevronDown, CircleHelp,
  CreditCard, Download, FileDown, Flag, LayoutDashboard, Menu, MoreHorizontal, Plus, Receipt,
  Search, Settings2, Sparkles, Target, TrendingUp, Upload, WalletCards, X,
} from "lucide-react";
import { toast } from "sonner";
import { loadFinanceState, reloadFinanceState } from "@/application/finance-service";
import {
  archiveGoal, createAccount, createBudget, createExpense, createGoal, createIncome, createTransfer,
  deleteBudget, deleteTransaction, updateGoal, updateTransaction,
} from "@/application/commands";
import { confirmOccurrence, createRecurringRule, occurrenceBucket, skipOccurrence } from "@/application/planned-service";
import { accountBalance, budgetUsage, deriveMetrics, liabilities, spendingInPeriod, transactionsWithinPeriod } from "@/domain/ledger";
import { moneyFromMajorUnits, moneyToMajorUnits } from "@/domain/money";
import type { ExpenseClassification, Goal, PlannedOccurrence, RecurringRule, Transaction as CanonicalTransaction } from "@/domain/entities";
import { defaultPeriodSettings, nextPeriod, periodContaining, periodLabel, previousComparablePeriod, type DateRange } from "@/domain/periods";
import { exportBackup, importBackup, savePeriodSettings } from "@/persistence/db";
import type { PersistedState } from "@/persistence/db";

type Section = "Resumen" | "Movimientos" | "Plan" | "Reportes";
type EntryKind = "Gasto" | "Ingreso" | "Transferencia";
type MovementFormEntry = { title: string; amount: number; kind: EntryKind; accountId: string; destinationAccountId?: string; categoryId?: string; classification?: ExpenseClassification };
type ViewTransaction = { id: string; title: string; category: string; account: string; date: string; amount: number; kind: EntryKind; icon: string; tone: string };

const navItems: { label: Section; icon: typeof LayoutDashboard }[] = [
  { label: "Resumen", icon: LayoutDashboard }, { label: "Movimientos", icon: Receipt }, { label: "Plan", icon: Target }, { label: "Reportes", icon: BarChart3 },
];
const emptyFinanceState: PersistedState = { accounts: [], categories: [], transactions: [], budgets: [], goals: [], recurringRules: [], plannedOccurrences: [], periodSettings: defaultPeriodSettings };

function formatCurrency(value: number, compact = false) { return new Intl.NumberFormat("es-DO", { style: "currency", currency: "DOP", maximumFractionDigits: 0, notation: compact ? "compact" : "standard" }).format(Math.abs(value)); }
function formatSignedCurrency(value: number) { return `${value >= 0 ? "+" : "−"}${formatCurrency(value)}`; }
function formatAccountBalance(value: number) { return value < 0 ? `−${formatCurrency(value)}` : formatCurrency(value); }
function formatDate(value: string) { const parsed = new Date(`${value.slice(0, 10)}T00:00:00`); return Number.isNaN(parsed.getTime()) ? value : new Intl.DateTimeFormat("es-DO", { day: "2-digit", month: "short", year: "numeric" }).format(parsed); }
function today() { return new Date().toISOString().slice(0, 10); }
function periodAtOffset(current: DateRange, offset: number) { let period = current; const step = offset >= 0 ? nextPeriod : previousComparablePeriod; for (let i = 0; i < Math.abs(offset); i += 1) period = step(period); return period; }
function initials(name: string) { return name.split(" ").map((part) => part[0]).join("").slice(0, 2).toUpperCase(); }
function colorFor(index: number) { return ["coral", "mint", "lavender", "sky"][index % 4]; }

function toViewTransactions(state: PersistedState): ViewTransaction[] {
  const accounts = new Map(state.accounts.map((item) => [item.id, item.name])); const categories = new Map(state.categories.map((item) => [item.id, item.name]));
  return [...state.transactions].sort((a, b) => b.date.localeCompare(a.date)).map((transaction) => {
    const income = transaction.kind === "income"; const transfer = transaction.kind === "transfer"; const source = accounts.get(transaction.accountId ?? "") ?? "Sin cuenta"; const destination = accounts.get(transaction.destinationAccountId ?? "");
    return { id: transaction.id, title: transaction.note ?? categories.get(transaction.categoryId ?? "") ?? "Movimiento", category: categories.get(transaction.categoryId ?? "") ?? (transfer ? "Transferencia" : income ? "Ingreso" : "Otros"), account: destination ? `${source} → ${destination}` : source, date: formatDate(transaction.date), amount: income ? moneyToMajorUnits(transaction.amount) : -moneyToMajorUnits(transaction.amount), kind: income ? "Ingreso" : transfer ? "Transferencia" : "Gasto", icon: income ? "↗" : transfer ? "⇄" : "•", tone: income ? "mint" : transfer ? "sky" : "coral" };
  });
}
function IconBubble({ transaction }: { transaction: ViewTransaction }) { return <div className={`transaction-icon ${transaction.tone}`} aria-hidden="true">{transaction.icon}</div>; }
function LogoMark() { return <div className="logo-mark" aria-hidden="true"><span /><span /><span /></div>; }
function SectionHeading({ eyebrow, title, description, action }: { eyebrow: string; title: string; description: string; action?: React.ReactNode }) { return <div className="section-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="heading-description">{description}</p></div>{action}</div>; }
function ModalShell({ title, eyebrow, onClose, children }: { title: string; eyebrow: string; onClose: () => void; children: React.ReactNode }) { return <div className="modal-backdrop" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}><div className="movement-modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><div className="modal-header"><div><p className="eyebrow">{eyebrow}</p><h2 id="modal-title">{title}</h2></div><button className="icon-button quiet" onClick={onClose} aria-label="Cerrar"><X size={18} /></button></div>{children}</div></div>; }
const plannedStatusMeta = { pending: { label: "Pendiente", icon: Receipt }, confirmed: { label: "Confirmado", icon: Check }, skipped: { label: "Omitido", icon: X }, overdue: { label: "Atrasado", icon: Flag } } as const;
function PlannedStatus({ status }: { status: PlannedOccurrence["status"] }) { const meta = plannedStatusMeta[status]; const Icon = meta.icon; return <small className={`status-label status-${status}`}><Icon size={12} /> {meta.label}</small>; }

function SummaryView({ state, period, periodOffset, onPeriodChange, onNewMovement, onSeeAll, onManagePlan, onAddAccount }: { state: PersistedState; period: DateRange; periodOffset: number; onPeriodChange: (offset: number) => void; onNewMovement: () => void; onSeeAll: () => void; onManagePlan: () => void; onAddAccount: () => void }) {
  const metrics = deriveMetrics(state); const spending = moneyToMajorUnits(spendingInPeriod(state.transactions, period)); const budgets = state.budgets.filter((item) => item.periodStart === period.start && item.periodEnd === period.end); const budgetTotal = budgets.reduce((sum, item) => sum + moneyToMajorUnits(item.amount), 0); const remaining = Math.max(0, budgetTotal - spending); const upcoming = state.plannedOccurrences.filter((item) => item.status !== "confirmed").sort((a, b) => a.scheduledDate.localeCompare(b.scheduledDate)).slice(0, 3); const rules = new Map(state.recurringRules.map((item) => [item.id, item]));
  const categoryRows = budgets.map((budget, index) => { const category = state.categories.find((item) => item.id === budget.categoryId); const used = moneyToMajorUnits(budgetUsage(state.transactions, budget.categoryId, period)); return { id: budget.id, label: category?.name ?? "Categoría archivada", used, total: moneyToMajorUnits(budget.amount), color: ["#ea6959", "#84b6a7", "#8a84b6", "#dfbc73"][index % 4] }; });
  return <><div className="hero-intro animate-in"><div><div className="status-pill"><span className="status-dot" /> {state.transactions.length ? "Todo está en orden" : "Empieza con tu primer movimiento"}</div><h1>Tu dinero, con claridad<span className="accent-period">.</span></h1><p>Panorama local al <strong>{formatDate(today())}</strong>.</p></div><div className="hero-actions"><button className="icon-button quiet" aria-label="Ayuda" onClick={() => toast.info("Prisma guarda tus datos únicamente en este dispositivo.")}><CircleHelp size={18} /></button><button className="icon-button quiet notification-button" aria-label="Notificaciones" onClick={() => toast.info(upcoming.length ? `${upcoming.length} eventos requieren tu atención.` : "No tienes notificaciones pendientes.")}><Bell size={18} /></button><button className="primary-button desktop-add" onClick={onNewMovement}><Plus size={17} /> Nuevo movimiento</button></div></div>
  <div className="metric-grid animate-in delay-1"><article className="metric-card featured-card"><div className="metric-card-top"><span>Disponible líquido</span><WalletCards size={19} /></div><div className="metric-value">{formatCurrency(moneyToMajorUnits(metrics.liquidPosition))}</div><div className="metric-foot"><span className="positive-trend"><ArrowUpRight size={15} /> Flujo real</span><span>actualizado ahora</span></div></article><article className="metric-card"><div className="metric-card-top"><span>Patrimonio neto</span><TrendingUp size={19} /></div><div className="metric-value">{formatCurrency(moneyToMajorUnits(metrics.netWorth))}</div><div className="metric-foot"><span>{state.accounts.length} cuentas</span><span>incluidas</span></div><div className="mini-progress"><span style={{ width: `${Math.min(100, Math.max(8, state.accounts.length * 18))}%` }} /></div></article><article className="metric-card warm-card"><div className="metric-card-top"><span>Deuda total</span><CreditCard size={19} /></div><div className="metric-value">{formatCurrency(moneyToMajorUnits(liabilities(state)))}</div><div className="debt-label"><span className="debt-dot" /> {liabilities(state) > 0 ? "Pasivos registrados" : "Sin pasivos registrados"}</div></article></div>
  <div className="dashboard-grid animate-in delay-2"><section className="panel spending-panel"><div className="panel-header"><div><p className="eyebrow">Seguimiento</p><h2>Gasto del período</h2></div><div className="period-controls"><button className="icon-button quiet" onClick={() => onPeriodChange(periodOffset - 1)} aria-label="Período anterior"><ArrowLeftRight size={15} /></button><span className="select-button">{periodLabel(period)}</span><button className="icon-button quiet" onClick={() => onPeriodChange(periodOffset + 1)} aria-label="Período siguiente"><ArrowUpRight size={15} /></button></div></div><div className="period-context"><button className="text-button" onClick={() => onPeriodChange(0)} disabled={periodOffset === 0}>{periodOffset === 0 ? "Período actual" : "Volver al actual"}</button></div><div className="spending-overview"><div><strong>{formatCurrency(spending)}</strong><span>{budgetTotal ? `de ${formatCurrency(budgetTotal)} presupuestados` : "Sin presupuesto configurado"}</span></div><div className="remaining-badge">{budgetTotal ? `Quedan ${formatCurrency(remaining)}` : "Añade un presupuesto"}</div></div><div className="budget-progress"><span style={{ width: `${budgetTotal ? Math.min(100, spending / budgetTotal * 100) : 0}%` }} /></div><div className="budget-legend"><span><i className="legend-dot coral-dot" /> Gastado <strong>{formatCurrency(spending)}</strong></span><span><i className="legend-dot pale-dot" /> Restante <strong>{formatCurrency(remaining)}</strong></span></div><div className="category-list">{categoryRows.length ? categoryRows.map((row) => <div className="category-row" key={row.id}><div className="category-row-name"><span className="category-color" style={{ background: row.color }} />{row.label}<span>{formatCurrency(row.used)} <em>/ {formatCurrency(row.total)}</em></span></div><div className="category-progress"><span style={{ width: `${Math.min(100, row.used / row.total * 100)}%`, background: row.color }} /></div></div>) : <p className="modal-note">Configura presupuestos desde Plan para seguir tus categorías.</p>}</div></section><section className="panel upcoming-panel"><div className="panel-header"><div><p className="eyebrow">Lo que viene</p><h2>Próximos pagos</h2></div><button className="text-button" onClick={onManagePlan}>Ver todos <ArrowUpRight size={15} /></button></div><div className="upcoming-list">{upcoming.length ? upcoming.map((occurrence) => { const rule = rules.get(occurrence.ruleId); return <div className="upcoming-item" key={occurrence.id}><div className="calendar-tile"><strong>{occurrence.scheduledDate.slice(8)}</strong><span>{occurrence.scheduledDate.slice(5, 7)}</span></div><div className="upcoming-copy"><strong>{rule?.title ?? "Regla archivada"}</strong><span>{occurrenceBucket(occurrence.scheduledDate)}</span><PlannedStatus status={occurrence.status} /></div><b>{rule ? formatCurrency(moneyToMajorUnits(rule.amount)) : "—"}</b></div>; }) : <div className="empty-inline"><Receipt size={16} /><span>No hay eventos próximos.</span></div>}</div><div className="upcoming-footer"><Sparkles size={16} /><span>Los eventos no afectan tu saldo hasta confirmarlos.</span><button className="text-button" onClick={onManagePlan}>Gestionar <ArrowUpRight size={14} /></button></div></section></div>
  <div className="bottom-grid animate-in delay-3"><section className="panel activity-panel"><div className="panel-header"><div><p className="eyebrow">Actividad real</p><h2>Movimientos recientes</h2></div><button className="text-button" onClick={onSeeAll}>Ver todos <ArrowUpRight size={15} /></button></div><div className="transaction-list">{toViewTransactions(state).slice(0, 4).map((transaction) => <TransactionRow key={transaction.id} transaction={transaction} />)}</div>{!state.transactions.length && <p className="modal-note">Tus movimientos aparecerán aquí.</p>}</section><section className="panel accounts-panel"><div className="panel-header"><div><p className="eyebrow">Dónde está tu dinero</p><h2>Cuentas</h2></div></div><div className="account-list">{state.accounts.filter((account) => !account.archived).slice(0, 4).map((account, index) => <AccountRow key={account.id} icon={initials(account.name)} name={account.name} kind={account.kind === "cash" ? "Efectivo" : account.kind === "credit" ? "Crédito" : "Banco"} value={formatAccountBalance(moneyToMajorUnits(accountBalance(account, state.transactions)))} color={colorFor(index)} />)}</div><button className="add-account-button" onClick={onAddAccount}><Plus size={16} /> Añadir cuenta</button></section></div></>;
}
function TransactionRow({ transaction, onEdit, onDelete }: { transaction: ViewTransaction; onEdit?: () => void; onDelete?: () => void }) { return <div className="transaction-row"><IconBubble transaction={transaction} /><div className="transaction-copy"><strong>{transaction.title}</strong><span>{transaction.category} · {transaction.account}</span></div><div className={`transaction-amount ${transaction.amount > 0 ? "income" : "expense"}`}><strong>{formatSignedCurrency(transaction.amount)}</strong><span>{transaction.date}</span></div>{onEdit && <button className="row-more" onClick={onEdit} aria-label={`Editar ${transaction.title}`}><MoreHorizontal size={17} /></button>}{onDelete && <button className="row-more" onClick={onDelete} aria-label={`Eliminar ${transaction.title}`}><X size={15} /></button>}</div>; }
function AccountRow({ icon, name, kind, value, color }: { icon: string; name: string; kind: string; value: string; color: string }) { return <div className="account-row"><div className={`account-icon ${color}`}>{icon}</div><div className="account-copy"><strong>{name}</strong><span>{kind}</span></div><strong className="account-value">{value}</strong></div>; }

function TransactionsView({ state, onNewMovement, onEdit, onDelete }: { state: PersistedState; onNewMovement: () => void; onEdit: (id: string) => void; onDelete: (id: string) => void }) {
  const [query, setQuery] = useState(""); const [kind, setKind] = useState<"all" | EntryKind>("all"); const [periodFilter, setPeriodFilter] = useState<"all" | "current">("current"); const period = periodContaining(today(), state.periodSettings); const all = toViewTransactions(state); const filtered = all.filter((item) => `${item.title} ${item.category} ${item.account}`.toLowerCase().includes(query.toLowerCase())).filter((item) => kind === "all" || item.kind === kind).filter((item) => periodFilter === "all" || transactionsWithinPeriod(state.transactions, period).some((source) => source.id === item.id));
  return <><SectionHeading eyebrow="Actividad real" title="Movimientos" description="Busca, revisa y corrige cada movimiento guardado localmente." action={<button className="primary-button" onClick={onNewMovement}><Plus size={17} /> Nuevo movimiento</button>} /><div className="filter-bar"><div className="search-field"><Search size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Buscar movimientos" /></div><select className="filter-button" value={periodFilter} onChange={(event) => setPeriodFilter(event.target.value as typeof periodFilter)}><option value="current">Este período</option><option value="all">Todos los períodos</option></select><select className="filter-button" value={kind} onChange={(event) => setKind(event.target.value as typeof kind)}><option value="all">Todos</option><option value="Gasto">Gastos</option><option value="Ingreso">Ingresos</option><option value="Transferencia">Transferencias</option></select></div><section className="panel transactions-page-panel"><div className="table-head"><span>Movimiento</span><span>Cuenta</span><span>Fecha</span><span className="align-right">Importe</span></div>{filtered.length ? filtered.map((transaction) => <div className="transaction-table-row" key={transaction.id}><div className="table-movement"><IconBubble transaction={transaction} /><div><strong>{transaction.title}</strong><span>{transaction.category}</span></div></div><span className="table-muted">{transaction.account}</span><span className="table-muted">{transaction.date}</span><div className="transaction-table-actions"><strong className={`align-right ${transaction.amount > 0 ? "income-text" : "expense-text"}`}>{formatSignedCurrency(transaction.amount)}</strong><button className="row-more" onClick={() => onEdit(transaction.id)} aria-label="Editar"><Settings2 size={14} /></button><button className="row-more" onClick={() => onDelete(transaction.id)} aria-label="Eliminar"><X size={14} /></button></div></div>) : <div className="empty-state"><Receipt size={22} /><strong>No encontramos movimientos</strong><span>Ajusta los filtros o registra un movimiento nuevo.</span></div>}</section></>;
}

function PlanView({ state, onNewRule, onNewBudget, onNewGoal, onOccurrenceChanged, onDeleteBudget, onEditGoal }: { state: PersistedState; onNewRule: () => void; onNewBudget: () => void; onNewGoal: () => void; onOccurrenceChanged: (id: string, action: "confirm" | "skip") => void; onDeleteBudget: (id: string) => void; onEditGoal: (goal: Goal) => void }) {
  const [tab, setTab] = useState<"presupuestos" | "metas" | "planificados">("presupuestos"); const [mode, setMode] = useState<"view" | "manage">("view"); const period = periodContaining(today(), state.periodSettings); const rules = state.recurringRules.filter((rule) => rule.active); const goals = state.goals.filter((goal) => !goal.archived); const occurrences = state.plannedOccurrences.filter((item) => item.status !== "confirmed").sort((a, b) => a.scheduledDate.localeCompare(b.scheduledDate)); const ruleById = new Map(rules.map((rule) => [rule.id, rule])); const budgets = state.budgets.filter((item) => item.periodStart === period.start && item.periodEnd === period.end); const available = moneyToMajorUnits(deriveMetrics(state).cashFlow) - budgets.reduce((sum, item) => sum + moneyToMajorUnits(item.amount), 0) - goals.reduce((sum, goal) => sum + moneyToMajorUnits(goal.allocatedAmount), 0);
  return <><SectionHeading eyebrow="Planificación" title="Plan" description="Presupuestos, metas y eventos futuros en un solo lugar." action={<div className="plan-heading-actions"><div className="mode-toggle" role="group" aria-label="Modo de Plan"><button className={mode === "view" ? "active" : ""} onClick={() => setMode("view")}><Search size={14} /> Ver</button><button className={mode === "manage" ? "active" : ""} onClick={() => setMode("manage")}><Settings2 size={14} /> Gestionar</button></div></div>} /><div className="plan-tabs" role="tablist">{([["presupuestos", "Presupuestos"], ["metas", "Metas"], ["planificados", "Planificados"]] as const).map(([value, label]) => <button key={value} className={tab === value ? "active" : ""} onClick={() => setTab(value)} role="tab" aria-selected={tab === value}>{label}{value === "planificados" && occurrences.length > 0 ? <span>{occurrences.length}</span> : null}</button>)}</div><div className="plan-summary-grid"><div className="plan-summary accent"><span>Disponible para planificar</span><strong>{formatCurrency(available)}</strong><small>Después de reservas actuales</small></div><div className="plan-summary"><span>{tab === "metas" ? "Metas activas" : "Reglas activas"}</span><strong>{tab === "metas" ? goals.length : rules.length}</strong><small>Datos guardados en este dispositivo</small></div><div className="plan-summary"><span>Eventos pendientes</span><strong>{occurrences.length}</strong><small>Revisa antes de confirmar</small></div></div>{tab === "metas" ? <section className="panel plan-full-panel"><div className="panel-header"><div><p className="eyebrow">Objetivos personales</p><h2>Metas</h2></div>{mode === "manage" && <button className="primary-button" onClick={onNewGoal}><Plus size={16} /> Nueva meta</button>}</div><div className="goal-grid">{goals.length ? goals.map((goal) => { const progress = Math.min(100, moneyToMajorUnits(goal.allocatedAmount) / moneyToMajorUnits(goal.targetAmount) * 100); return <article className="goal-card" key={goal.id}><div className="goal-card-top"><div className="goal-icon"><Target size={17} /></div>{mode === "manage" && <button className="row-more" onClick={() => onEditGoal(goal)} aria-label={`Editar ${goal.name}`}><MoreHorizontal size={17} /></button>}</div><strong>{goal.name}</strong><span>{formatCurrency(moneyToMajorUnits(goal.allocatedAmount))} de {formatCurrency(moneyToMajorUnits(goal.targetAmount))}</span><div className="category-progress"><span style={{ width: `${progress}%` }} /></div><small>{Math.round(progress)}% completado{goal.targetDate ? ` · objetivo ${formatDate(goal.targetDate)}` : ""}</small></article>; }) : <div className="empty-state"><Target size={22} /><strong>Aún no tienes metas</strong><span>Define un objetivo y reserva dinero sin mezclarlo con tus gastos.</span>{mode === "manage" && <button className="wide-secondary" onClick={onNewGoal}><Plus size={15} /> Crear mi primera meta</button>}</div>}</div></section> : <div className="plan-content-grid"><section className="panel"><div className="panel-header"><div><p className="eyebrow">Este período</p><h2>{tab === "presupuestos" ? "Presupuestos" : "Reglas activas"}</h2></div>{mode === "manage" && <button className="text-button" onClick={tab === "presupuestos" ? onNewBudget : onNewRule}><Plus size={15} /> Añadir</button>}</div>{tab === "presupuestos" ? <div className="plan-budget-list">{budgets.length ? budgets.map((budget, index) => { const category = state.categories.find((item) => item.id === budget.categoryId); const used = moneyToMajorUnits(budgetUsage(state.transactions, budget.categoryId, period)); return <div className="plan-budget-row" key={budget.id}><div className="plan-budget-top"><span><i className="category-color" style={{ background: ["#ea6959", "#84b6a7", "#8a84b6"][index % 3] }} />{category?.name ?? "Categoría"}</span><strong>{formatCurrency(Math.max(0, moneyToMajorUnits(budget.amount) - used))} <em>restante</em></strong>{mode === "manage" && <button className="row-more" onClick={() => onDeleteBudget(budget.id)} aria-label="Eliminar presupuesto"><X size={14} /></button>}</div><div className="category-progress"><span style={{ width: `${Math.min(100, used / moneyToMajorUnits(budget.amount) * 100)}%`, background: ["#ea6959", "#84b6a7", "#8a84b6"][index % 3] }} /></div><span className="plan-budget-meta">{formatCurrency(used)} gastado de {formatCurrency(moneyToMajorUnits(budget.amount))}</span></div>; }) : <p className="modal-note">No hay presupuestos para {periodLabel(period)}.</p>}</div> : <div className="rule-list">{rules.length ? rules.map((rule) => <div className="rule-row" key={rule.id}><div className="rule-icon"><Receipt size={16} /></div><div><strong>{rule.title}</strong><span>{rule.frequency} · {formatCurrency(moneyToMajorUnits(rule.amount))}</span></div><b>{rule.active ? "Activa" : "Pausada"}</b></div>) : <p className="modal-note">No hay reglas activas.</p>}</div>}</section><section className="panel"><div className="panel-header"><div><p className="eyebrow">Eventos planificados</p><h2>Próximos pagos</h2></div>{mode === "manage" && <button className="text-button" onClick={onNewRule}><Plus size={15} /> Nueva regla</button>}</div>{occurrences.length ? occurrences.slice(0, 8).map((occurrence) => { const rule = ruleById.get(occurrence.ruleId); return <div className="planned-card" key={occurrence.id}><div className="calendar-tile"><strong>{occurrence.scheduledDate.slice(8)}</strong><span>{occurrence.scheduledDate.slice(5, 7)}</span></div><div className="planned-copy"><strong>{rule?.title ?? "Regla archivada"}</strong><span>{occurrenceBucket(occurrence.scheduledDate)} · {formatDate(occurrence.scheduledDate)}</span><PlannedStatus status={occurrence.status} /></div><b>{rule ? formatCurrency(moneyToMajorUnits(rule.amount)) : "—"}</b>{mode === "manage" && occurrence.status !== "skipped" && <div className="planned-actions"><button className="icon-button quiet" onClick={() => onOccurrenceChanged(occurrence.id, "confirm")} aria-label="Confirmar"><Check size={14} /></button><button className="icon-button quiet" onClick={() => onOccurrenceChanged(occurrence.id, "skip")} aria-label="Omitir"><X size={14} /></button></div>}</div>; }) : <p className="modal-note">No hay eventos pendientes. Crea una regla recurrente para empezar.</p>}{mode === "manage" && <button className="wide-secondary" onClick={onNewRule}><Plus size={15} /> Añadir regla recurrente</button>}</section></div>}</>;
}

function ReportsView({ state }: { state: PersistedState }) {
  const period = periodContaining(today(), state.periodSettings); const current = transactionsWithinPeriod(state.transactions, period); const spent = moneyToMajorUnits(spendingInPeriod(state.transactions, period)); const income = current.filter((item) => item.kind === "income").reduce((sum, item) => sum + moneyToMajorUnits(item.amount), 0); const categoryRows = state.categories.filter((category) => !category.archived).map((category) => ({ name: category.name, amount: moneyToMajorUnits(budgetUsage(current, category.id, period)) })).filter((row) => row.amount > 0).sort((a, b) => b.amount - a.amount); const total = categoryRows.reduce((sum, row) => sum + row.amount, 0) || 1; const max = Math.max(...categoryRows.map((row) => row.amount), 1); const average = state.transactions.length ? moneyToMajorUnits(spendingInPeriod(state.transactions, period)) : 0;
  return <><SectionHeading eyebrow="Análisis" title="Reportes" description="Lee tus hábitos con datos reales de tu historial local." action={<span className="filter-button">{periodLabel(period)}</span>} /><div className="report-highlight"><div><p className="eyebrow">Gasto del período</p><strong>{formatCurrency(spent)}</strong><span><span className="positive-trend"><ArrowDownRight size={14} /> {income ? `${Math.round(spent / income * 100)}%` : "0%"}</span> del ingreso registrado</span></div><div className="report-chart">{[...Array(6)].map((_, index) => { const value = state.transactions.filter((item) => item.kind === "expense").slice(index * 3, index * 3 + 3).reduce((sum, item) => sum + moneyToMajorUnits(item.amount), 0); return <div className="chart-column" key={index}><div className="chart-bar" style={{ height: `${Math.max(5, value / max * 100)}%` }} /><span>{index + 1}</span></div>; })}</div></div><div className="report-grid"><section className="panel"><div className="panel-header"><div><p className="eyebrow">Distribución</p><h2>Por categoría</h2></div></div><div className="donut-layout"><div className="donut-chart"><div><strong>{formatCurrency(total)}</strong><span>total</span></div></div><div className="donut-legend">{categoryRows.length ? categoryRows.slice(0, 5).map((row, index) => <span key={row.name}><i style={{ background: ["#ea6959", "#84b6a7", "#8a84b6", "#dfbc73", "#6e9fb3"][index] }} /> {row.name} <b>{Math.round(row.amount / total * 100)}%</b></span>) : <p className="modal-note">Aún no hay gastos categorizados en este período.</p>}</div></div></section><section className="panel insight-panel"><div className="insight-kicker"><Sparkles size={16} /> Lectura local</div><h2>{spent === 0 ? "Tu historia empieza aquí" : "Tu flujo está visible"}</h2><p>{spent === 0 ? "Registra movimientos para que Prisma pueda mostrar tendencias y distribución por categoría." : `La categoría con más gasto es ${categoryRows[0]?.name ?? "Otros"}. El total del período es ${formatCurrency(spent)} y puedes compararlo con tus presupuestos en Plan.`}</p><div className="report-facts"><span><b>{current.length}</b> movimientos</span><span><b>{state.goals.filter((goal) => !goal.archived).length}</b> metas activas</span><span><b>{average ? formatCurrency(average) : "—"}</b> gasto actual</span></div></section></div></>;
}

function NewMovementModal({ state, onClose, onSave }: { state: PersistedState; onClose: () => void; onSave: (entry: MovementFormEntry) => void }) { const [kind, setKind] = useState<EntryKind>("Gasto"); const [title, setTitle] = useState(""); const [amount, setAmount] = useState(""); const accounts = state.accounts.filter((item) => !item.archived); const categories = state.categories.filter((item) => !item.archived); const [accountId, setAccountId] = useState(accounts[0]?.id ?? ""); const [destinationAccountId, setDestinationAccountId] = useState(accounts[1]?.id ?? accounts[0]?.id ?? ""); const [categoryId, setCategoryId] = useState(categories.find((item) => item.type !== "income")?.id ?? ""); const [classification, setClassification] = useState<ExpenseClassification>("occasional"); const canSave = Boolean(title.trim() && Number(amount) > 0 && accountId && (kind === "Transferencia" ? destinationAccountId && accountId !== destinationAccountId : categoryId)); return <ModalShell title="Nuevo movimiento" eyebrow="Acción local" onClose={onClose}><div className="kind-toggle" role="tablist">{(["Gasto", "Ingreso", "Transferencia"] as EntryKind[]).map((item) => <button key={item} className={kind === item ? "active" : ""} onClick={() => setKind(item)}>{item}</button>)}</div><label className="form-label">Monto<input autoFocus value={amount} onChange={(event) => setAmount(event.target.value)} placeholder="0.00" inputMode="decimal" /></label><label className="form-label">Descripción<input value={title} onChange={(event) => setTitle(event.target.value)} placeholder="¿Qué ocurrió?" /></label><div className="form-grid"><label className="form-label">Cuenta<select value={accountId} onChange={(event) => setAccountId(event.target.value)}>{accounts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>{kind === "Transferencia" ? <label className="form-label">Destino<select value={destinationAccountId} onChange={(event) => setDestinationAccountId(event.target.value)}>{accounts.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label> : <label className="form-label">Categoría<select value={categoryId} onChange={(event) => setCategoryId(event.target.value)}>{categories.filter((item) => kind === "Ingreso" ? item.type !== "expense" : item.type !== "income").map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label>}</div>{kind === "Gasto" && <label className="form-label">Clasificación<select value={classification} onChange={(event) => setClassification(event.target.value as ExpenseClassification)}><option value="fixed">Fijo</option><option value="variable">Variable</option><option value="occasional">Ocasional</option></select></label>}<p className="modal-note">Se guarda en Dexie y funciona sin conexión.</p><button className="primary-button modal-save" disabled={!canSave} onClick={() => onSave({ title: title.trim(), amount: Number(amount), kind, accountId, destinationAccountId: kind === "Transferencia" ? destinationAccountId : undefined, categoryId, classification: kind === "Gasto" ? classification : undefined })}><Check size={17} /> Guardar movimiento</button></ModalShell>; }

function AccountModal({ onClose, onSaved }: { onClose: () => void; onSaved: (name: string, kind: "cash" | "bank" | "credit", openingBalance: number) => void }) { const [name, setName] = useState(""); const [kind, setKind] = useState<"cash" | "bank" | "credit">("bank"); const [balance, setBalance] = useState(""); return <ModalShell title="Nueva cuenta" eyebrow="Patrimonio local" onClose={onClose}><label className="form-label">Nombre<input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder="Banco, efectivo o tarjeta" /></label><label className="form-label">Tipo<select value={kind} onChange={(event) => setKind(event.target.value as typeof kind)}><option value="bank">Banco</option><option value="cash">Efectivo</option><option value="credit">Tarjeta de crédito</option></select></label><label className="form-label">Saldo inicial<input value={balance} onChange={(event) => setBalance(event.target.value)} inputMode="decimal" placeholder="0.00" /></label><button className="primary-button modal-save" disabled={!name.trim()} onClick={() => onSaved(name, kind, Number(balance) || 0)}><Check size={17} /> Crear cuenta</button></ModalShell>; }
function RuleModal({ state, onClose, onSaved }: { state: PersistedState; onClose: () => void; onSaved: () => void }) { const [title, setTitle] = useState(""); const [amount, setAmount] = useState(""); const [frequency, setFrequency] = useState<RecurringRule["frequency"]>("monthly"); const [startsOn, setStartsOn] = useState(today()); const account = state.accounts.find((item) => !item.archived); const category = state.categories.find((item) => item.type !== "income" && !item.archived); return <ModalShell title="Nueva regla recurrente" eyebrow="Intención futura" onClose={onClose}><label className="form-label">Descripción<input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} placeholder="Alquiler, nómina, internet" /></label><label className="form-label">Monto<input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="0.00" /></label><div className="form-grid"><label className="form-label">Frecuencia<select value={frequency} onChange={(event) => setFrequency(event.target.value as typeof frequency)}><option value="weekly">Semanal</option><option value="biweekly">Quincenal</option><option value="monthly">Mensual</option><option value="yearly">Anual</option></select></label><label className="form-label">Primera fecha<input type="date" value={startsOn} onChange={(event) => setStartsOn(event.target.value)} /></label></div><p className="modal-note">Cuenta: {account?.name ?? "crea una cuenta primero"}. Categoría: {category?.name ?? "crea una categoría"}.</p><button className="primary-button modal-save" disabled={!title.trim() || Number(amount) <= 0 || !account || !category} onClick={async () => { try { await createRecurringRule({ title, amount: moneyFromMajorUnits(Number(amount)), kind: "expense", accountId: account!.id, categoryId: category!.id, classification: "fixed", frequency, startsOn, active: true }); onSaved(); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo crear la regla"); } }}><Check size={17} /> Crear regla</button></ModalShell>; }
function BudgetModal({ state, onClose, onSaved }: { state: PersistedState; onClose: () => void; onSaved: () => void }) { const period = periodContaining(today(), state.periodSettings); const [categoryId, setCategoryId] = useState(state.categories.find((item) => item.type !== "income" && !item.archived)?.id ?? ""); const [amount, setAmount] = useState(""); return <ModalShell title="Nuevo presupuesto" eyebrow="Límite del período" onClose={onClose}><label className="form-label">Categoría<select value={categoryId} onChange={(event) => setCategoryId(event.target.value)}>{state.categories.filter((item) => item.type !== "income" && !item.archived).map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</select></label><label className="form-label">Monto del período<input autoFocus value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" placeholder="0.00" /></label><p className="modal-note">Se aplicará a {periodLabel(period)}.</p><button className="primary-button modal-save" disabled={!categoryId || Number(amount) <= 0} onClick={async () => { try { await createBudget({ categoryId, periodStart: period.start, periodEnd: period.end, amount: moneyFromMajorUnits(Number(amount)) }); onSaved(); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo crear el presupuesto"); } }}><Check size={17} /> Guardar presupuesto</button></ModalShell>; }
function GoalModal({ goal, onClose, onSaved }: { goal?: Goal; onClose: () => void; onSaved: () => void }) { const [name, setName] = useState(goal?.name ?? ""); const [target, setTarget] = useState(goal ? String(moneyToMajorUnits(goal.targetAmount)) : ""); const [allocated, setAllocated] = useState(goal ? String(moneyToMajorUnits(goal.allocatedAmount)) : ""); const [targetDate, setTargetDate] = useState(goal?.targetDate ?? ""); return <ModalShell title={goal ? "Editar meta" : "Nueva meta"} eyebrow="Objetivo personal" onClose={onClose}><label className="form-label">Nombre<input autoFocus value={name} onChange={(event) => setName(event.target.value)} placeholder="Fondo de emergencia, viaje…" /></label><div className="form-grid"><label className="form-label">Objetivo<input value={target} onChange={(event) => setTarget(event.target.value)} inputMode="decimal" placeholder="0.00" /></label><label className="form-label">Asignado<input value={allocated} onChange={(event) => setAllocated(event.target.value)} inputMode="decimal" placeholder="0.00" /></label></div><label className="form-label">Fecha objetivo <input type="date" value={targetDate} onChange={(event) => setTargetDate(event.target.value)} /></label><button className="primary-button modal-save" disabled={!name.trim() || Number(target) <= 0 || Number(allocated) < 0 || Number(allocated) > Number(target)} onClick={async () => { try { if (goal) await updateGoal(goal.id, { name, targetAmount: moneyFromMajorUnits(Number(target)), allocatedAmount: moneyFromMajorUnits(Number(allocated)), targetDate: targetDate || undefined }); else await createGoal({ name, targetAmount: moneyFromMajorUnits(Number(target)), allocatedAmount: moneyFromMajorUnits(Number(allocated)), targetDate: targetDate || undefined }); onSaved(); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo guardar la meta"); } }}><Check size={17} /> {goal ? "Guardar cambios" : "Crear meta"}</button>{goal && <button className="wide-secondary" onClick={async () => { await archiveGoal(goal.id); onSaved(); }}>Archivar meta</button>}</ModalShell>; }
function EditMovementModal({ transaction, onClose, onSaved }: { transaction: CanonicalTransaction; onClose: () => void; onSaved: () => void }) { const [title, setTitle] = useState(transaction.note ?? ""); const [amount, setAmount] = useState(String(moneyToMajorUnits(transaction.amount))); return <ModalShell title="Editar movimiento" eyebrow="Corrección local" onClose={onClose}><label className="form-label">Descripción<input autoFocus value={title} onChange={(event) => setTitle(event.target.value)} /></label><label className="form-label">Monto<input value={amount} onChange={(event) => setAmount(event.target.value)} inputMode="decimal" /></label><button className="primary-button modal-save" disabled={!title.trim() || Number(amount) <= 0} onClick={async () => { try { await updateTransaction(transaction.id, { note: title, amount: moneyFromMajorUnits(Number(amount)) }); onSaved(); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo actualizar"); } }}><Check size={17} /> Guardar cambios</button></ModalShell>; }

function SettingsModal({ initialDay, onClose, onSave, onExport, onImport }: { initialDay: number; onClose: () => void; onSave: (day: number) => void; onExport: () => void; onImport: (file: File) => void }) { const [day, setDay] = useState(String(initialDay)); const input = useRef<HTMLInputElement>(null); return <ModalShell title="Ajustes y privacidad" eyebrow="Preferencias locales" onClose={onClose}><label className="form-label">Día de inicio del período<select value={day} onChange={(event) => setDay(event.target.value)}>{Array.from({ length: 31 }, (_, index) => <option key={index + 1} value={index + 1}>{index + 1}</option>)}</select></label><p className="modal-note">Tus datos no salen de este dispositivo. El día 25 crea períodos del 25 al 24.</p><button className="primary-button modal-save" onClick={() => onSave(Number(day))}><Check size={17} /> Guardar preferencias</button><div className="settings-actions"><button className="wide-secondary" onClick={onExport}><Download size={15} /> Exportar backup</button><button className="wide-secondary" onClick={() => input.current?.click()}><Upload size={15} /> Importar backup</button><input ref={input} hidden type="file" accept="application/json" onChange={(event) => { const file = event.target.files?.[0]; if (file) onImport(file); }} /></div></ModalShell>; }

export default function Home() {
  const [activeSection, setActiveSection] = useState<Section>("Resumen"); const [state, setState] = useState<PersistedState | null>(null); const [periodOffset, setPeriodOffset] = useState(0); const [mobileMenu, setMobileMenu] = useState(false); const [modal, setModal] = useState<"movement" | "settings" | "rule" | "account" | "budget" | "goal" | "edit" | null>(null); const [editingId, setEditingId] = useState<string | null>(null); const [editingGoal, setEditingGoal] = useState<Goal | undefined>();
  useEffect(() => { let mounted = true; void loadFinanceState([]).then((loaded) => { if (mounted) setState(loaded); }); return () => { mounted = false; }; }, []);
  const current = state ?? emptyFinanceState; const viewTransactions = useMemo(() => toViewTransactions(current), [current]); const period = periodAtOffset(periodContaining(today(), current.periodSettings), periodOffset);
  const refresh = async () => setState(await reloadFinanceState()); const goTo = (section: Section) => { setActiveSection(section); setMobileMenu(false); window.scrollTo({ top: 0, behavior: "smooth" }); };
  const saveMovement = async ({ title, amount, kind, accountId, destinationAccountId, categoryId, classification }: MovementFormEntry) => { try { const input = { id: `tx-${Date.now()}`, date: today(), amount, accountId, destinationAccountId, categoryId, classification, note: title }; const result = kind === "Ingreso" ? await createIncome(input) : kind === "Transferencia" ? await createTransfer(input) : await createExpense(input); await refresh(); setModal(null); toast.success("Movimiento guardado", { description: title }); result.warnings?.forEach((warning) => toast.warning(warning)); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo guardar el movimiento"); } };
  const saveSettings = async (day: number) => { try { await savePeriodSettings({ startDay: day }); await refresh(); setPeriodOffset(0); setModal(null); toast.success("Preferencias guardadas"); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudieron guardar los ajustes"); } };
  const saveAccount = async (name: string, kind: "cash" | "bank" | "credit", openingBalance: number) => { try { await createAccount({ name, kind, openingBalance }); await refresh(); setModal(null); toast.success("Cuenta creada"); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo crear la cuenta"); } };
  const deleteMovement = async (id: string) => { if (!window.confirm("¿Eliminar este movimiento? Esta acción no se puede deshacer.")) return; try { await deleteTransaction(id); await refresh(); toast.success("Movimiento eliminado"); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo eliminar"); } };
  const editTransaction = (id: string) => { setEditingId(id); setModal("edit"); };
  const handleOccurrence = async (id: string, action: "confirm" | "skip") => { try { await (action === "confirm" ? confirmOccurrence(id) : skipOccurrence(id)); await refresh(); toast.success(action === "confirm" ? "Ocurrencia confirmada" : "Ocurrencia omitida"); } catch (error) { toast.error(error instanceof Error ? error.message : "No se pudo actualizar el evento"); } };
  const exportLocal = async () => { const backup = await exportBackup(); const blob = new Blob([JSON.stringify(backup, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = `prisma-backup-${today()}.json`; anchor.click(); URL.revokeObjectURL(url); toast.success("Backup exportado"); };
  const importLocal = async (file: File) => { try { await importBackup(JSON.parse(await file.text())); await refresh(); setModal(null); toast.success("Backup restaurado"); } catch (error) { toast.error(error instanceof Error ? error.message : "El backup no es válido"); } };
  const editingTransaction = editingId ? current.transactions.find((item) => item.id === editingId) : undefined;
  return <div className="app-shell"><aside className={`sidebar ${mobileMenu ? "mobile-open" : ""}`}><div className="brand"><LogoMark /><div><strong>Prisma</strong><span>PRIVADO / LOCAL</span></div></div><div className="sidebar-context"><span className="context-label">Espacio personal</span><button>Mi espacio <ChevronDown size={14} /></button></div><nav className="primary-nav" aria-label="Navegación principal">{navItems.map(({ label, icon: Icon }) => <button key={label} className={activeSection === label ? "active" : ""} onClick={() => goTo(label)}><Icon size={18} /><span>{label}</span>{label === "Plan" && current.plannedOccurrences.filter((item) => item.status !== "confirmed").length > 0 && <i className="nav-badge">{current.plannedOccurrences.filter((item) => item.status !== "confirmed").length}</i>}</button>)}</nav><div className="sidebar-bottom"><div className="offline-card"><div className="offline-icon"><Check size={14} /></div><div><strong>Solo en tu dispositivo</strong><span>Datos privados y offline</span></div></div><button className="secondary-nav-button" onClick={() => { setModal("settings"); setMobileMenu(false); }}><Settings2 size={17} /> Ajustes</button><button className="secondary-nav-button" onClick={exportLocal}><Download size={17} /> Backup</button><div className="user-profile"><div className="avatar">PR</div><div><strong>Mi espacio</strong><span>Plan personal</span></div><MoreHorizontal size={18} /></div></div></aside>{mobileMenu && <button className="sidebar-scrim" onClick={() => setMobileMenu(false)} aria-label="Cerrar menú" />}<main className="main-content"><header className="mobile-header"><button className="mobile-menu icon-button quiet" onClick={() => setMobileMenu(true)} aria-label="Abrir menú"><Menu size={20} /></button><div className="brand mobile-brand"><LogoMark /><strong>Prisma</strong></div><button className="icon-button quiet notification-button" onClick={() => toast.info("No hay notificaciones nuevas.")} aria-label="Notificaciones"><Bell size={18} /></button></header><div className="content-wrap">{activeSection === "Resumen" && <SummaryView state={current} period={period} periodOffset={periodOffset} onPeriodChange={setPeriodOffset} onNewMovement={() => setModal("movement")} onSeeAll={() => goTo("Movimientos")} onManagePlan={() => goTo("Plan")} onAddAccount={() => setModal("account")} />}{activeSection === "Movimientos" && <TransactionsView state={current} onNewMovement={() => setModal("movement")} onEdit={editTransaction} onDelete={deleteMovement} />}{activeSection === "Plan" && <PlanView state={current} onNewRule={() => setModal("rule")} onNewBudget={() => setModal("budget")} onNewGoal={() => { setEditingGoal(undefined); setModal("goal"); }} onOccurrenceChanged={handleOccurrence} onDeleteBudget={async (id) => { if (window.confirm("¿Eliminar este presupuesto?")) { await deleteBudget(id); await refresh(); toast.success("Presupuesto eliminado"); } }} onEditGoal={(goal) => { setEditingGoal(goal); setModal("goal"); }} />}{activeSection === "Reportes" && <ReportsView state={current} />}</div></main><nav className="mobile-nav" aria-label="Navegación móvil">{navItems.map(({ label, icon: Icon }) => <button key={label} className={activeSection === label ? "active" : ""} onClick={() => goTo(label)}><Icon size={19} /><span>{label}</span></button>)}</nav><button className="mobile-fab" onClick={() => setModal("movement")} aria-label="Nuevo movimiento"><Plus size={22} /></button>{modal === "movement" && <NewMovementModal state={current} onClose={() => setModal(null)} onSave={saveMovement} />}{modal === "settings" && <SettingsModal initialDay={current.periodSettings.startDay} onClose={() => setModal(null)} onSave={saveSettings} onExport={exportLocal} onImport={importLocal} />}{modal === "rule" && <RuleModal state={current} onClose={() => setModal(null)} onSaved={async () => { await refresh(); setModal(null); toast.success("Regla creada"); }} />}{modal === "account" && <AccountModal onClose={() => setModal(null)} onSaved={saveAccount} />}{modal === "budget" && <BudgetModal state={current} onClose={() => setModal(null)} onSaved={async () => { await refresh(); setModal(null); toast.success("Presupuesto guardado"); }} />}{modal === "goal" && <GoalModal goal={editingGoal} onClose={() => setModal(null)} onSaved={async () => { await refresh(); setModal(null); toast.success(editingGoal ? "Meta actualizada" : "Meta creada"); }} />}{modal === "edit" && editingTransaction && <EditMovementModal transaction={editingTransaction} onClose={() => setModal(null)} onSaved={async () => { await refresh(); setModal(null); toast.success("Movimiento actualizado"); }} />}</div>;
}
